public class Main {
    public static void main(String[] args) {
        int tracker = 0;
        int lastI = 0;

        for (int i = 1; i <= 3; i++) {
            lastI = i;
            tracker += i * 10;
            System.out.println("Pass #" + i + " -> tracker is now: " + tracker);
        }

        System.out.println("Loop finished!");
        System.out.println("Last processed i: " + lastI);
        System.out.println("Final tracker value: " + tracker);
    }
}

