public class Main {
    public static void main(String[] args) {
        int product = 1;
        for (int i = 1; i <= 4; i++) {
            product *= i;
            System.out.println("Pass " + i + ": " + product);
        }
        System.out.println("Final Product: " + product);
    }
}

public class Main {
    public static void main(String[] args) {
        int sum = 0;
        for (int i = 1; i <= 5; i++) {
            if (i % 2 != 0) {
                sum += i;
            } else {
                sum -= i;
            }
        }
        System.out.println("Alternating Sum: " + sum);
    }
}

public class Main {
    public static void main(String[] args) {
        int a = 0, b = 1;
        System.out.print(a + " " + b + " ");
        for (int i = 3; i <= 6; i++) {
            int next = a + b;
            System.out.print(next + " ");
            a = b;
            b = next;
        }
        System.out.println();
    }
}

public class Main {
