public class Main {
    public static void main(String[] args) {
        int max = 0;
        for (int i = 1; i <= 5; i++) {
            int val = (i * 7) % 11;
            if (val > max) {
                max = val;
            }
        }
        System.out.println("Maximum Value Found: " + max);
    }
}
